const sel = String($json.business_unit != null ? $json.business_unit : ($json['field-0'] != null ? $json['field-0'] : 'ALL')).toUpperCase();
const chosen = sel === 'ALL' ? CASES : CASES.filter(c => c.input.business_unit === sel);
if (chosen.length === 0) return [{ json: { _name: '(none)', _expect: {}, _empty: true, business_unit: sel } }];
return chosen.map(c => ({ json: { ...c.input, _mode: 'test', _name: c.name, _expect: c.expect } }));

const cases = $('Golden Set').all();
const outs = $input.all();
const results = [];
for (let i = 0; i < cases.length; i++) {
  const cj = cases[i].json;
  if (cj._empty) { results.push({ json: { name: 'no cases for ' + cj.business_unit, pass: true, skipped: true, diffs: [] } }); continue; }
  const exp = cj._expect || {};
  const got = (outs[i] && outs[i].json) || {};
  const diffs = [];
  for (const k of Object.keys(exp)) {
    if (got[k] !== exp[k]) diffs.push(k + ': expected ' + JSON.stringify(exp[k]) + ', got ' + JSON.stringify(got[k]));
  }
  results.push({ json: { name: cj._name, pass: diffs.length === 0, diffs } });
}
return results;

const rows = $input.all().map(i => i.json);
const real = rows.filter(r => !r.skipped);
const passed = real.filter(r => r.pass).length;
const failed = real.length - passed;
const lines = rows.map(r => (r.skipped ? '-     ' : (r.pass ? 'PASS  ' : 'FAIL  ')) + r.name +
  (r.diffs && r.diffs.length ? '\n        ' + r.diffs.join('\n        ') : ''));
const head = failed ? (failed + ' FAILED, ' + passed + ' passed') : ('All ' + passed + ' passed');
const summary = head + ' (of ' + real.length + ')\n\n' + lines.join('\n');
let sel = 'ALL';
try { const f = $('Run Regression Test').first().json; sel = String(f.business_unit != null ? f.business_unit : (f['field-0'] != null ? f['field-0'] : 'ALL')).toUpperCase(); } catch (e) {}
const icon = failed ? ':red_circle:' : ':large_green_circle:';
const slack_payload = { text: icon + ' Regression ' + head + ' (' + sel + ')', blocks: [
  { type: 'header', text: { type: 'plain_text', text: 'Regression test: ' + sel } },
  { type: 'section', text: { type: 'mrkdwn', text: icon + ' *' + head + '*  (of ' + real.length + ')' } },
  { type: 'section', text: { type: 'mrkdwn', text: '```' + lines.join('\n').slice(0, 2800) + '```' } },
] };
return [{ json: { passed, failed, total: real.length, all_pass: failed === 0, summary, slack_payload } }];
